import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the golden vectors generated by color_matching's
/// `ColorMatching.WeightedSquaredError` solver. The corpus is deliberately
/// shared rather than recreated here: it includes exclusions, zero-weight
/// omissions, and exact earliest-index tie cases that are easy to drift from.
final class WeightedSquaredErrorParityCorpusTests: XCTestCase {
    func testCorpusMetadataDeclaresTheSharedSelectionContract() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.lightSources, ["white", "red", "green", "blue", "lps"])
    }

    func testWeightedSquaredErrorAndSolverMatchEveryCorpusScenarioExactly() throws {
        let corpus = try loadCorpus()
        let scorer = WeightedSquaredErrorScorer()

        for scenario in corpus.scenarios {
            let weights = makeWeights(scenario.weights)
            let target = TargetResponseVector(makeChannels(scenario.target.channels))
            let palette = scenario.palette
                .sorted { $0.index < $1.index }
                .map(makePaletteColor)
            let expectedScores = scenario.expected.scores.sorted { $0.index < $1.index }

            XCTAssertEqual(palette.map(\.id), expectedScores.map(\.index), scenario.id)

            let actualScores = palette.map {
                scorer.score(candidate: $0, target: target, weights: weights)
            }
            assertScores(
                actualScores,
                match: expectedScores,
                scenarioID: scenario.id
            )

            let selected = try solveSelection(
                palette: palette,
                target: target,
                weights: weights
            )
            assertSelection(
                selected,
                palette: palette,
                scores: actualScores,
                expected: scenario.expected,
                scenarioID: scenario.id
            )
        }
    }

    private func loadCorpus() throws -> ParityCorpus {
        let testDirectory = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        let fixture = testDirectory
            .appendingPathComponent("Fixtures")
            .appendingPathComponent("WeightedSquaredError")
            .appendingPathComponent("v1")
            .appendingPathComponent("corpus.json")
        let data = try Data(contentsOf: fixture)
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(ParityCorpus.self, from: data)
    }

    private func makePaletteColor(_ vector: ParityVector) -> PaletteColor {
        PaletteColor(
            id: vector.index ?? -1,
            hex: vector.hexColor,
            rgb: RGBColor(hex: vector.hexColor)!,
            responses: makeChannels(vector.channels).mapValues(IlluminationResponse.init(brightness:))
        )
    }

    private func makeChannels(_ channels: [String: Double]) -> [LightingCondition: Double] {
        Dictionary(uniqueKeysWithValues: channels.compactMap { name, value in
            LightingCondition(rawValue: name).map { ($0, value) }
        })
    }

    private func makeWeights(_ weights: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: weights["white"] ?? 0,
            red: weights["red"] ?? 0,
            green: weights["green"] ?? 0,
            blue: weights["blue"] ?? 0,
            lps: weights["lps"] ?? 0
        )
    }

    private func solveSelection(
        palette: [PaletteColor],
        target: TargetResponseVector,
        weights: ChannelWeights
    ) throws -> (index: Int?, error: Double?) {
        let sourceGrids = Dictionary(uniqueKeysWithValues: weights.activeEntries.compactMap { entry in
            target.value(for: entry.condition).map {
                (entry.condition, BrightnessGrid(width: 1, height: 1, values: [$0]))
            }
        })

        // A missing required target cannot be represented as a source grid.
        // Its exclusion is asserted through scorer outcomes above.
        guard sourceGrids.count == weights.activeEntries.count else {
            return (nil, nil)
        }

        let result = try CompositionSolver().solve(
            palette: palette,
            sourceGrids: sourceGrids,
            weights: weights
        )
        return (result.colorIndex(x: 0, y: 0), result.error(x: 0, y: 0).isFinite ? result.error(x: 0, y: 0) : nil)
    }

    private func assertScores(
        _ actual: [ScorerResult],
        match expected: [ParityScore],
        scenarioID: String
    ) {
        XCTAssertEqual(actual.count, expected.count, scenarioID)
        for (actualScore, expectedScore) in zip(actual, expected) {
            switch (actualScore, expectedScore.outcome) {
            case (.excluded, .excluded):
                break
            case (.score(let actualValue), .score(let expectedValue)):
                XCTAssertEqual(actualValue, expectedValue, scenarioID)
            default:
                XCTFail("\(scenarioID): candidate \(expectedScore.index) outcome differs from the corpus")
            }
        }
    }

    private func assertSelection(
        _ selection: (index: Int?, error: Double?),
        palette: [PaletteColor],
        scores: [ScorerResult],
        expected: ParityExpected,
        scenarioID: String
    ) {
        XCTAssertEqual(selection.index, expected.selectedIndex, scenarioID)
        XCTAssertEqual(selection.error, expected.error, scenarioID)
        if let index = selection.index {
            XCTAssertEqual(palette[index].hex, expected.selectedHexColor, scenarioID)
        } else {
            XCTAssertNil(expected.selectedHexColor, scenarioID)
        }

        guard let expectedError = expected.error else {
            XCTAssertNil(expected.tieBroke, scenarioID)
            XCTAssertEqual(expected.tiedIndices, [], scenarioID)
            return
        }

        let actualTiedIndices = scores.enumerated().compactMap { index, result -> Int? in
            guard case .score(let score) = result, score == expectedError else { return nil }
            return index
        }
        XCTAssertEqual(actualTiedIndices, expected.tiedIndices, scenarioID)
        XCTAssertEqual(expected.tieBroke, actualTiedIndices.count > 1, scenarioID)
        XCTAssertEqual(selection.index, actualTiedIndices.first, scenarioID)
    }
}

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let missingPolicy: String
    let lightSources: [String]
    let scenarios: [ParityScenario]
}

private struct ParityScenario: Decodable {
    let id: String
    let weights: [String: Double]
    let target: ParityVector
    let palette: [ParityVector]
    let expected: ParityExpected
}

private struct ParityVector: Decodable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]
}

private struct ParityExpected: Decodable {
    let error: Double?
    let scores: [ParityScore]
    let selectedHexColor: String?
    let selectedIndex: Int?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ParityScore: Decodable {
    enum Outcome: Equatable {
        case excluded
        case score(Double)
    }

    let index: Int
    let outcome: Outcome

    private enum CodingKeys: String, CodingKey {
        case index
        case score
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        index = try container.decode(Int.self, forKey: .index)
        let score = try container.decode(StringOrDouble.self, forKey: .score)
        switch score {
        case .string("excluded"):
            outcome = .excluded
        case .double(let value):
            outcome = .score(value)
        case .string(let value):
            throw DecodingError.dataCorruptedError(
                forKey: .score,
                in: container,
                debugDescription: "Unknown parity outcome: \(value)"
            )
        }
    }
}

private enum StringOrDouble: Decodable {
    case string(String)
    case double(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .double(value)
        } else {
            self = .string(try container.decode(String.self))
        }
    }
}
